function strings(asLesson=false){open(`<div class="eyebrow">${asLesson?'LESSON 03':'SOUND LAB'} · LISTENING</div><h2>Four strings. Four voices.</h2><p class="modal-sub">Tap each open-string reference tone. Listen from low G to high E. These are synthesized pitches, not recordings of a violin.</p><div class="string-board">${[['G',196,'G3'],['D',293.66,'D4'],['A',440,'A4'],['E',659.25,'E5']].map(([n,f,p])=>`<div class="string-row"><button data-tone="${f}" aria-label="Play ${p}">${n}</button><div class="string-line"></div><small>${p}</small></div>`).join('')}</div><div class="feedback" role="status">Listen to all four tones to unlock a listening check.</div><button class="primary" id="stringCheck" disabled>Try a listening check →</button>`);let heard=new Set();document.querySelectorAll('[data-tone]').forEach(b=>b.onclick=()=>{tone(+b.dataset.tone);heard.add(b.dataset.tone);$('.feedback').textContent=`${heard.size} of 4 reference pitches explored.`;$('#stringCheck').disabled=heard.size<4;});$('#stringCheck').onclick=()=>ear(asLesson);}
function ear(asLesson=false){const a=196,b=440;open('<div class="eyebrow">EAR TRAINING · PITCH COMPARISON</div><h2>Follow the pitch.</h2><p class="modal-sub">Listen to two tones, then decide which was higher. You can replay as often as you like.</p><button class="primary" id="listen">▶ Play two tones</button><div class="choices"><button data-ear="0" disabled>First tone</button><button data-ear="1" disabled>Second tone</button></div><div class="feedback" role="status"></div>');let reversed=Math.random()>.5,correct=reversed?0:1;$('#listen').onclick=()=>{tone(reversed?b:a,.6);tone(reversed?a:b,.6,.9);document.querySelectorAll('[data-ear]').forEach(x=>x.disabled=false);};document.querySelectorAll('[data-ear]').forEach(x=>x.onclick=()=>{if(+x.dataset.ear===correct){$('.feedback').innerHTML='Yes. A higher pitch comes from a faster vibration.<div class="modal-actions"><button class="primary" id="earDone">'+(asLesson?'Complete lesson':'Practice again')+'</button></div>';document.querySelectorAll('[data-ear]').forEach(x=>x.disabled=true);$('#earDone').onclick=()=>asLesson?(completed(2),close()):ear();}else{$('.feedback').textContent='Try listening again. Focus on which tone sounds higher, rather than louder.';}});}
function rhythm(asLesson=false){open(`<div class="eyebrow">${asLesson?'LESSON 02':'PRACTICE'} · FIND YOUR PULSE</div><h2>A steady place to start.</h2><p class="modal-sub">At 60 beats per minute, each beat is one second apart. First listen to four beats, then tap four times at the same pace. Your first tap starts your timing check.</p><div class="rhythm-dots"><b></b><b></b><b></b><b></b></div><button class="primary" id="count">▶ Listen to four beats</button><button class="tap" id="tap" disabled>Tap</button><div class="feedback" role="status">Listen first, then keep the pulse going.</div><div id="rhythmActions"></div>`);let timeouts=[],times=[],ready=false;cleanup=()=>timeouts.forEach(clearTimeout);$('#count').onclick=()=>{timeouts.forEach(clearTimeout);times=[];ready=false;$('#tap').disabled=true;$('#count').disabled=true;$('#rhythmActions').innerHTML='';for(let i=0;i<4;i++)timeouts.push(setTimeout(()=>{tone(i===0?880:660,.12);document.querySelectorAll('.rhythm-dots b').forEach((d,j)=>d.classList.toggle('lit',i===j));},i*1000));timeouts.push(setTimeout(()=>{ready=true;$('#tap').disabled=false;$('#tap').focus();$('.feedback').textContent='Your turn. Tap four times, one second apart.';document.querySelectorAll('.rhythm-dots b').forEach(d=>d.classList.remove('lit'));},3700));};$('#tap').onclick=()=>{if(!ready)return;times.push(performance.now());document.querySelectorAll('.rhythm-dots b').forEach((d,i)=>d.classList.toggle('lit',i===times.length-1));tone(440,.08);$('#tap').textContent=times.length+' / 4';if(times.length===4){ready=false;$('#tap').disabled=true;$('#count').disabled=false;const error=times.slice(1).reduce((s,t,i)=>s+Math.abs(t-times[i]-1000),0)/3;const score=Math.max(0,Math.round(100-error/10));state.attempts.push({at:new Date().toISOString(),score,averageErrorMs:Math.round(error)});save();$('.feedback').textContent=`Timing score: ${score}%. Your average gap differed from one second by ${Math.round(error)} ms. ${score>=70?'A steady start.':'Listen again, then try relaxed, even taps.'}`;$('#rhythmActions').innerHTML=`<button class="secondary" id="retryRhythm">Try again</button>${asLesson&&score>=70?' <button class="primary" id="rhythmDone">Complete lesson →</button>':''}`;$('#retryRhythm').onclick=()=>rhythm(asLesson);if($('#rhythmDone'))$('#rhythmDone').onclick=()=>{completed(1);close();};}};}
function kit(asLesson=false){open(`<div class="eyebrow">${asLesson?'LESSON 05':'AT-HOME KIT'} · MOVEMENT AWARENESS</div><h2>Your hands are enough.</h2><p class="modal-sub">You need a comfortable chair and a tabletop. No violin substitute is required for this exercise.</p><div class="card path" style="background:#f6e9dd"><h3>Finger independence · about 1 minute</h3><p class="modal-sub">1. Rest your forearm comfortably, with a relaxed wrist.<br>2. Lightly tap index, middle, ring, and little finger in order.<br>3. Repeat slowly five times. Keep your shoulder relaxed.<br>4. Try the sequence in reverse.</p></div><p class="fine">Use gentle taps. Stop if anything hurts. This rehearses finger sequencing; it does not teach violin string pressure, fingering distances, or instrument posture. Household objects should not be pressed against your neck or used to imitate string resistance.</p><label><input type="checkbox" id="kitConfirm" style="width:auto;margin-right:8px">I tried the sequence comfortably in both directions.</label><button class="primary" id="kitDone" disabled>${asLesson?'Record self-reported practice':'Save practice'} →</button>`);$('#kitConfirm').onchange=e=>$('#kitDone').disabled=!e.target.checked;$('#kitDone').onclick=()=>{state.kit=true;save();if(asLesson)completed(4);toast('Movement practice saved as self-reported.');close();};}
